Rules.InvariantScript:
UpdateContext(
    {
        varVisibleContainerDerFluAero: true,
        varVisibleContainerDerFluOutros: false,
        //Default color border
        varBordaDefault: RGBA(
            0,
            0,
            0,
            1
        )
    }
)

Clear(col_derFluImg);
Reset(cmbDerFluHoraCadastro);
Reset(cmbDerFluMinuCadastro);
Reset(dropDerFluFluido);
Reset(dropDerFluOrigemVazamento);
Reset(TxtDerFluMatAero);
Reset(TxtDerFluModAero);
Reset(dropDerFluCiaAerea);
Reset(TxtDerFluPrefixoNome);
Reset(TxtDerFluOrigem);
Reset(TxtDerFluOrigemNumVoo);
Reset(TxtDerFluDestino);
Reset(TxtDerFluDestinoNumVoo);
Reset(dropDerFluLocalAero);
Reset(TxtDerFluPosicaoAero);
Reset(cmbDerFluAreaManchaAero);
Reset(TxtDerFluAreaLitrosAero);
Reset(TxtDerFluRelatoFiscal);
Reset(TxtDerFluCausaDano);
Reset(TxtDerFluMedIsolamento);
Reset(TxtDerFluNumEquipa);
Reset(TxtDerFluDescEquipa);
Reset(TxtDerFluEmpresa);
Reset(cmbDerFluAtendVoo);
Reset(TxtDerFluCondNome);
Reset(TxtDerFluCondMat);
Reset(dropDerFluLocalOutros);
Reset(TxtDerFluPosicaoOutros);
Reset(cmbDerFluAreaManchaOutros);
Reset(TxtDerFluAreaLitrosOutros);
Reset(TxtDerFluRelatoCondutor)

If(
    dropDerFluFluido.Selected.Value = "Outro" Or dropDerFluFluido.Selected.Value = "Internacional",
    UpdateContext(
        {
            varResultCompAerea: "Nome da comp.",
            varDisplayCompAerea: DisplayMode.Edit
        }
    ),
    If(
        dropDerFluCiaAerea.Selected.Value = "Aviação geral",
        UpdateContext(
            {
                varResultCompAerea: "Prefixo:",
                varDisplayCompAerea: DisplayMode.Edit
            }
        ),
        UpdateContext(
            {
                varResultCompAerea: "",
                varDisplayCompAerea: DisplayMode.Disabled
            }
        )
    )
)

If(
    Self.Selected.Value = "Aeronave" Or IsBlank(Self.Selected.Value) = true,
    UpdateContext(
        {
            varVisibleContainerDerFluAero: true,
            varVisibleContainerDerFluOutros: false,
            varDisplayRelatoCondutor: DisplayMode.Disabled
        }
    ),
    UpdateContext(
        {
            varVisibleContainerDerFluAero: false,
            varVisibleContainerDerFluOutros: true,
            varDisplayRelatoCondutor: DisplayMode.Edit
        }
    )
)

If(
    dropDerFluCiaAerea.Selected.Value = "Outro" Or dropDerFluCiaAerea.Selected.Value = "Internacional",
    UpdateContext(
        {
            varResultCompAerea: "Nome da comp.",
            varDisplayCompAerea: DisplayMode.Edit
        }
    ),
    If(
        dropDerFluCiaAerea.Selected.Value = "Aviação geral",
        UpdateContext(
            {
                varResultCompAerea: "Prefixo:",
                varDisplayCompAerea: DisplayMode.Edit
            }
        ),
        UpdateContext(
            {
                varResultCompAerea: "",
                varDisplayCompAerea: DisplayMode.Disabled
            }
        )
    )
)

If(
    IsBlank(AddMediaButtonDerFlu.Media) = false,
    Collect(
        col_derFluImg,
        {
            id: Value(
                First(
                    SortByColumns(
                        Filter(
                            col_derFluImg,
                            id >= 0
                        ),
                        "id",
                        SortOrder.Descending
                    )
                ).id + 1
            ),
            img: UploadedImageDerFlu.Image
        }
    )
);
Reset(AddMediaButtonDerFlu)

UpdateContext(
    {
        varVisibleSpinerDerFluCadastrar: true,
        varFormErro: false,
        varDerFluId: Value(
            First(
                SortByColumns(
                    Filter(
                        '14.2-tbl_DerramamentoDeFluidos',
                        derFlu_id > 0
                    ),
                    "ID",
                    SortOrder.Descending
                )
            ).derFlu_id + 1
        )
    }
);
Switch(
    true,
    cmbDerFluHoraCadastro.Selected.Value = "hor",
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    cmbDerFluMinuCadastro.Selected.Value = "min",
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(dropDerFluFluido.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(dropDerFluOrigemVazamento.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluMatAero.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluModAero.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(dropDerFluCiaAerea.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And dropDerFluCiaAerea.Selected.Value = "Aviação geral" And IsBlank(TxtDerFluPrefixoNome.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And dropDerFluCiaAerea.Selected.Value = "Internacional" And IsBlank(TxtDerFluPrefixoNome.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluOrigem.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluOrigemNumVoo.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluDestino.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluDestinoNumVoo.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(dropDerFluLocalAero.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And dropDerFluLocalAero.Selected.Value = "Posição de estacionamento" And IsBlank(TxtDerFluPosicaoAero.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(cmbDerFluAreaManchaAero.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value = "Aeronave" And IsBlank(TxtDerFluAreaLitrosAero.Text) = true,////////////////////////
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluNumEquipa.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluDescEquipa.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluEmpresa.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(cmbDerFluAtendVoo.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluCondNome.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluCondMat.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(dropDerFluLocalOutros.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And dropDerFluLocalOutros.Selected.Value = "Posição de estacionamento" And IsBlank(TxtDerFluPosicaoOutros.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(cmbDerFluAreaManchaOutros.Selected.Value) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluAreaLitrosOutros.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtDerFluRelatoFiscal.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtDerFluCausaDano.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    IsBlank(TxtDerFluMedIsolamento.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    dropDerFluOrigemVazamento.Selected.Value <> "Aeronave" And IsBlank(TxtDerFluRelatoCondutor.Text) = true,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    CountRows(col_derFluImg) = 0,
    UpdateContext(
        {
            varFormErro: true,
            varBordaDefault: Color.Red
        }
    ),
    UpdateContext(
        {varFormErro: false
            //;varBordaDefault: Color.Red
}
    )
);
If(
    varFormErro = true,
    Notify(
        "Atenção todas as informações devem ser preenchidas!",
        NotificationType.Error
    ),
    //Insert de dados no database------------------------------------------------------------------------------
    Patch(
        '14.2-tbl_DerramamentoDeFluidos',
        Defaults('14.2-tbl_DerramamentoDeFluidos'),
        {
            derFlu_id: varDerFluId,
            derFlu_data: dtpDerFluDataCadastro.SelectedDate,
            derFlu_hora: cmbDerFluHoraCadastro.Selected.Value & ":" & cmbDerFluMinuCadastro.Selected.Value,
            derFlu_fluido: dropDerFluFluido.Selected.Value,
            derFlu_tipo: dropDerFluOrigemVazamento.Selected.Value,
            derFlu_matricula: TxtDerFluMatAero.Text,
            derFlu_modelo: TxtDerFluModAero.Text,
            derFlu_ciaAerea: dropDerFluCiaAerea.Selected.Value,
            derFlu_prefixoNome: TxtDerFluPrefixoNome.Text,
            derFlu_origemVoo: TxtDerFluOrigem.Text,
            derFlu_numVooOrigem: TxtDerFluOrigemNumVoo.Text,
            derFlu_destinoVoo: TxtDerFluDestino.Text,
            derFlu_numVooDestino: TxtDerFluDestinoNumVoo.Text,
            derFlu_local: dropDerFluLocalAero.Selected.Value & dropDerFluLocalOutros.Selected.Value,
            derFlu_posEstacionamento: TxtDerFluPosicaoAero.Text & TxtDerFluPosicaoOutros.Text,
            derFlu_areaFluido: cmbDerFluAreaManchaAero.Selected.Value & cmbDerFluAreaManchaOutros.Selected.Value,
            derFlu_litroFluido: TxtDerFluAreaLitrosAero.Text & TxtDerFluAreaLitrosOutros.Text,
            derFlu_relato: TxtDerFluRelatoFiscal.Text,
            derFlu_causaDanos: TxtDerFluCausaDano.Text,
            derFlu_medIsolamento: TxtDerFluMedIsolamento.Text,
            //outras origens
            derFlu_numEquipa: TxtDerFluNumEquipa.Text,
            derFlu_equipa: TxtDerFluDescEquipa.Text,
            derFlu_empresa: TxtDerFluEmpresa.Text,
            derFlu_atendVoo: cmbDerFluAtendVoo.Selected.Value,
            derFlu_condutor: TxtDerFluCondNome.Text,
            derFlu_matCondutor: TxtDerFluCondMat.Text,
            derFlu_relCondutor: TxtDerFluRelatoCondutor.Text,
            derFlu_bloco: varBlocoUser,
            derFlu_aeroporto: varAeroUser
        }
    );
    //inset das imagens
ForAll(
        col_derFluImg,
        Patch(
            '14.2-tbl_DerFluidosImg',
            Defaults('14.2-tbl_DerFluidosImg'),
            {
                derFluFK_id: varDerFluId,
                derFluImg_imagem: img
            }
        )
    );
    ForAll(
        Filter(
            tbl_userNotify,
            ID_FK_MODULO = 37
        ),
        'Airportnow-notificaçãoderramamentodefluídos'.Run(
            ThisRecord.EMAIL_USER,
            "Aeroporto: " & varIATAUser & " - " & varAeroUser & " - Bloco " & varBlocoUser,
            "Registrado por: " & varNomeUser,
            "Data: " & dtpDerFluDataCadastro.SelectedDate & " - " & cmbDerFluHoraCadastro.Selected.Value & ":" & cmbDerFluMinuCadastro.Selected.Value,
            "Fluído: " & dropDerFluFluido.Selected.Value,
            "Origem do vazamento: " & dropDerFluOrigemVazamento.Selected.Value,
            If(
                dropDerFluOrigemVazamento.Selected.Value = "Aeronave",
                "Matrícula: " & TxtDerFluMatAero.Text,
                "Código: " & TxtDerFluNumEquipa.Text
            ),
            If(
                dropDerFluOrigemVazamento.Selected.Value = "Aeronave",
                "Modelo: " & TxtDerFluModAero.Text,
                "Equipamento: " & TxtDerFluDescEquipa.Text
            ),
            If(
                dropDerFluOrigemVazamento.Selected.Value = "Aeronave",
                "Operador: " & dropDerFluCiaAerea.Selected.Value & " " & TxtDerFluPrefixoNome.Text,
                "Empresa: " & TxtDerFluEmpresa.Text
            ),
            If(
                dropDerFluOrigemVazamento.Selected.Value = "Aeronave",
                "Origem: " & TxtDerFluOrigem.Text & " - " & TxtDerFluOrigemNumVoo.Text,
                "Em atendimento ao voo? " & cmbDerFluAtendVoo.Selected.Value
            ),
            If(
                dropDerFluOrigemVazamento.Selected.Value = "Aeronave",
                "Destino: " & TxtDerFluDestino.Text & " - " & TxtDerFluDestinoNumVoo.Text,
                "Condutor: " & TxtDerFluCondNome.Text & " - " & TxtDerFluCondMat.Text
            ),
            "Local do derramamento: " & dropDerFluLocalAero.Selected.Value & dropDerFluLocalOutros.Selected.Value & " - " & TxtDerFluPosicaoAero.Text & TxtDerFluPosicaoOutros.Text,
            "Área da mancha: " & cmbDerFluAreaManchaAero.Selected.Value & cmbDerFluAreaManchaOutros.Selected.Value,
            "Litros: " & TxtDerFluAreaLitrosAero.Text & TxtDerFluAreaLitrosOutros.Text,
            "Relato do fiscal: " & TxtDerFluRelatoFiscal.Text,
            "Possível causa e dano: " & TxtDerFluCausaDano.Text,
            "Medidas de isolamento e contingência: " & TxtDerFluMedIsolamento.Text,
            If(
                dropDerFluOrigemVazamento.Selected.Value <> "Aeronave",
                "Relato do condutor: " & TxtDerFluRelatoCondutor.Text,
                ""
            )
        )
    );
    Select(ButtonResetFormDerFlu);
    Navigate(
        ScreenSucesso,
        ScreenTransition.Fade,
        {var_navigateSucess: ScreenDerramamentoFluido}
    )
);
UpdateContext({varVisibleSpinerDerFluCadastrar: false})
